// Squillo's page: the run, the capture readback and the live pitch line (UI-012).
'use strict';
const WORKER_SRC = "// The engine's worker (ADR 0006): runs the engine module on each block and\n// posts each frame's pitch cell to the page; at Stop, the take's measures\n// and every cell of the run (UI-017).\nlet ex = null;\nlet mem = null;\nlet port = null;\nself.onmessage = async (e) => {\n  const m = e.data;\n  if (m.type === 'init') {\n    const { instance } = await WebAssembly.instantiate(m.wasm, {});\n    ex = instance.exports;\n    self.postMessage({ type: 'ready' });\n  } else if (m.type === 'start') {\n    ex.start(m.raw ? 1 : 0, m.rateMatched ? 1 : 0);\n    port = m.port;\n    port.onmessage = (ev) => {\n      const block = ev.data;\n      const bp = ex.block_ptr();\n      mem = new Float32Array(ex.memory.buffer, bp, 128);\n      mem.set(block);\n      const t0 = performance.now();\n      const n = ex.push();\n      if (n > 0) {\n        const ptr = ex.out_ptr();\n        const out = new Float64Array(ex.memory.buffer, ptr, 4 * n).slice();\n        self.postMessage({ type: 'frames', out, ms: performance.now() - t0 });\n      }\n    };\n  } else if (m.type === 'finish') {\n    if (port) port.onmessage = null;\n    port = null;\n    // finish() may grow the module's memory, which detaches any earlier\n    // view of it: take the buffer only after the call returns.\n    const ptr = ex.finish();\n    const take = new Float64Array(ex.memory.buffer, ptr, 11).slice();\n    const cp = ex.cells_ptr(), n = ex.cells_len();\n    const cells = new Float64Array(ex.memory.buffer, cp, 3 * n).slice();\n    const np = ex.notes_ptr(), k = ex.notes_len();\n    const notes = new Float64Array(ex.memory.buffer, np, 2 * k).slice();\n    self.postMessage({ type: 'take', take, cells, notes }, [cells.buffer, notes.buffer]);\n  }\n};\n";
const WORKLET_SRC = "// Capture (ADR 0002): forwards every 128-sample render quantum of the first\n// channel, unchanged and in order, to the engine's worker, and a copy to the\n// page, which holds the take in memory (UI-015).\nclass Capture extends AudioWorkletProcessor {\n  constructor() {\n    super();\n    this.out = null;\n    this.port.onmessage = (e) => { this.out = e.data.port; };\n  }\n  process(inputs) {\n    const ch = inputs[0] && inputs[0][0];\n    if (ch && this.out) {\n      const b = new Float32Array(ch);\n      const keep = new Float32Array(ch);\n      this.out.postMessage(b, [b.buffer]);\n      this.port.postMessage(keep, [keep.buffer]);\n    }\n    return true;\n  }\n}\nregisterProcessor('squillo-capture', Capture);\n";
const WASM_B64 = "";

const LOW = 1200 * Math.log2(82.4068892282175 / 440); // E2, cents from A4
const HIGH = 1200 * Math.log2(1046.5022612023945 / 440); // C6
const SPAN_FRAMES = 1000; // 8 s
// UI-012: one scale per run, fixed at Start from the previous run's measured
// frames; only these two bounds outlive a run.
let nextScale = [LOW, HIGH];
let scale = nextScale;

function scaleFrom(cents) {
  if (cents.length < 125) return null;
  const v = cents.slice().sort((a, b) => a - b);
  const q = (p) => v[Math.min(v.length - 1, Math.floor(p * v.length))];
  let lo = q(0.02) - 400, hi = q(0.98) + 400;
  if (hi - lo < 1800) { const m = (lo + hi) / 2; lo = m - 900; hi = m + 900; }
  if (lo < LOW) { hi += LOW - lo; lo = LOW; }
  if (hi > HIGH) { lo = Math.max(LOW, lo - (hi - HIGH)); hi = HIGH; }
  return [lo, hi];
}

const $ = (id) => document.getElementById(id);
const canvas = $('line');
const ctx2d = canvas.getContext('2d');
let frames = []; // [index, state, cents, U]
let run = null;
let tally = null; // the whole run's counts, kept past the line's trimming (UI-015)
let computeMs = [];
let take = null; // the stopped run's blocks, in memory only (UI-015)
let blocks = [];
let play = null; // { ac, src, t0, from, loop } while the take plays; loop is [start, end] s or null
let mark = 0; // UI-017: the take's instant last heard or chosen, in seconds
let playInfo = { contexts: 0, gain: null, samples: 0 };
const worker = new Worker(URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' })));
const wasm = Uint8Array.from(atob(WASM_B64), (c) => c.charCodeAt(0));
const ready = new Promise((res) => {
  worker.onmessage = (e) => { if (e.data.type === 'ready') res(); };
});
worker.postMessage({ type: 'init', wasm });
window.squillo = { scale: () => scale, frames: () => frames, computeMs: () => computeMs, take: () => take, playInfo: () => playInfo };

function onFrames(e) {
  if (e.data.type === 'take') { showMeasures(e.data.take); showTakeLine(e.data.cells, e.data.notes); return; }
  // Frames still in flight when Stop is pressed belong to no line (UI-012).
  if (e.data.type !== 'frames' || !run) return;
  const o = e.data.out;
  for (let i = 0; i < o.length; i += 4) {
    frames.push([o[i], o[i + 1], o[i + 2], o[i + 3]]);
    tally.all++;
    if (o[i + 1] === 2) {
      tally.measured++; tally.cents.push(o[i + 2]);
      tally.stretch++; tally.longest = Math.max(tally.longest, tally.stretch);
    } else tally.stretch = 0;
  }
  computeMs.push(e.data.ms);
  if (frames.length > 4 * SPAN_FRAMES) frames = frames.slice(-SPAN_FRAMES);
}

function css(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }

// UI-012's rules for a frame, shared by the live line and the take's line
// (UI-017): f is [index, state, cents, U]; dx is one frame's width.
function drawFrames(ctx2d, view, x, y, dx, h, lo, hi) {
  ctx2d.fillStyle = css('--band');
  for (const f of view) {
    if (f[1] !== 2) continue;
    const top = y(f[2] + f[3]), bot = y(f[2] - f[3]);
    ctx2d.fillRect(x(f[0]) - 0.5, top, dx + 1, Math.max(1, bot - top));
  }
  ctx2d.strokeStyle = css('--line');
  ctx2d.lineWidth = 2;
  ctx2d.beginPath();
  let joined = false;
  let prev = -2;
  for (const f of view) {
    if (f[1] !== 2) { joined = false; continue; }
    if (joined && f[0] === prev + 1) ctx2d.lineTo(x(f[0]), y(f[2]));
    else ctx2d.moveTo(x(f[0]), y(f[2]));
    joined = true;
    prev = f[0];
  }
  ctx2d.stroke();
  // A measured frame beyond the scale is marked at the edge it passed.
  ctx2d.fillStyle = css('--line');
  for (const f of view) {
    if (f[1] !== 2 || (f[2] >= lo && f[2] <= hi)) continue;
    const up = f[2] > hi, e = up ? 2 : h - 2, t = up ? 8 : -8;
    ctx2d.beginPath();
    ctx2d.moveTo(x(f[0]) - 4, e + t); ctx2d.lineTo(x(f[0]) + 4, e + t); ctx2d.lineTo(x(f[0]), e);
    ctx2d.fill();
  }
}

function draw() {
  const w = canvas.width, h = canvas.height, pad = 12;
  ctx2d.clearRect(0, 0, w, h);
  const [lo, hi] = scale;
  const y = (c) => pad + (h - 2 * pad) * (1 - (c - lo) / (hi - lo));
  const last = frames.length ? frames[frames.length - 1][0] : 0;
  const x = (i) => w - (last - i) * (w / SPAN_FRAMES);
  const view = frames.filter((f) => last - f[0] < SPAN_FRAMES);
  drawFrames(ctx2d, view, x, y, w / SPAN_FRAMES, h, lo, hi);
  if (run) requestAnimationFrame(draw);
}

function rawFrom(s) {
  // Raw only when the three flags read back off (ADR 0002); unreported is not raw.
  return s.echoCancellation === false && s.noiseSuppression === false && s.autoGainControl === false;
}

async function start() {
  $('start').disabled = true;
  // iOS (Safari and every iOS browser, all WebKit) runs audio only for a
  // context created and resumed within the tap itself, before any await;
  // one created after getUserMedia stays suspended and no block ever arrives.
  const ac = new AudioContext({ sampleRate: 48000 });
  const resumed = ac.resume();
  try {
    await ready;
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false, channelCount: 1 },
    });
    await resumed;
    if (ac.state !== 'running') throw new Error('the browser did not start audio. Tap Start again.');
    if (ac.sampleRate !== 48000) throw new Error('This browser cannot run audio at 48 000 Hz, so the measure would not be the one tested.');
    const track = stream.getAudioTracks()[0];
    const s = track.getSettings();
    const raw = rawFrom(s);
    const rateMatched = s.sampleRate === ac.sampleRate;
    const url = URL.createObjectURL(new Blob([WORKLET_SRC], { type: 'text/javascript' }));
    await ac.audioWorklet.addModule(url);
    // WebKit renders only nodes the destination pulls: the capture node feeds
    // the destination through a gain of 0, so nothing is heard.
    const node = new AudioWorkletNode(ac, 'squillo-capture', { numberOfInputs: 1, numberOfOutputs: 1 });
    const mute = ac.createGain();
    mute.gain.value = 0;
    node.connect(mute).connect(ac.destination);
    const ch = new MessageChannel();
    worker.onmessage = onFrames;
    worker.postMessage({ type: 'start', raw, rateMatched, port: ch.port2 }, [ch.port2]);
    node.port.postMessage({ port: ch.port1 }, [ch.port1]);
    stopPlay();
    take = null;
    blocks = [];
    $('after').hidden = true;
    $('live').hidden = false;
    node.port.onmessage = (ev) => blocks.push(ev.data);
    ac.createMediaStreamSource(stream).connect(node);
    frames = [];
    computeMs = [];
    scale = nextScale;
    tally = { all: 0, measured: 0, stretch: 0, longest: 0, cents: [] };
    const processed = ['echoCancellation', 'noiseSuppression', 'autoGainControl'].filter((k) => s[k] !== false);
    run = { stream, ac, node, processed };
    const parts = [];
    parts.push(raw ? 'Raw capture: the browser reports no echo cancellation, noise suppression or gain control.'
      : 'Not raw: the browser applies ' + ['echoCancellation', 'noiseSuppression', 'autoGainControl'].filter((k) => s[k] !== false).join(', ') + ', so every ± is widened by 1.11 and may still be too small.');
    if (!rateMatched) parts.push('The browser does not report the microphone running at 48 000 Hz, so each ± includes the resampling bridge.');
    $('condition').textContent = parts.join(' ');
    $('condition').hidden = false;
    $('state').textContent = 'Listening. Sing.';
    $('stop').disabled = false;
    requestAnimationFrame(draw);
  } catch (err) {
    ac.close();
    $('state').textContent = 'Could not start: ' + err.message;
    $('start').disabled = false;
  }
}

function stop() {
  if (!run) return;
  run.stream.getTracks().forEach((t) => t.stop());
  run.ac.close();
  worker.postMessage({ type: 'finish' });
  const processed = run.processed;
  run = null;
  $('stop').disabled = true;
  $('start').disabled = false;
  // UI-012: the line is not shown once the run ends, and nothing of it kept.
  nextScale = scaleFrom(tally.cents) ?? nextScale;
  const { all, measured, longest } = tally;
  tally = null;
  frames = [];
  draw();
  $('live').hidden = true;
  const n = blocks.reduce((a, b) => a + b.length, 0);
  const samples = new Float32Array(n);
  let o = 0;
  for (const b of blocks) { samples.set(b, o); o += b.length; }
  blocks = [];
  let peak = 0;
  for (const v of samples) peak = Math.max(peak, Math.abs(v));
  take = { samples, peak, rate: 48000, scale, cells: null, notes: [] };
  mark = 0;
  $('take').hidden = true;
  const secs = (x) => x.toLocaleString('en', { maximumFractionDigits: 1 });
  $('state').textContent = 'Stopped. The microphone is closed.';
  $('summary').textContent = `You sang for ${secs(n / 48000)} s. ${measured} of ${all} frames had a measurable pitch; `
    + `the longest unbroken stretch lasted ${secs(longest * 0.008)} s.`;
  $('measures').replaceChildren();
  $('measures').hidden = true;
  $('processednote').textContent = processed.length ? `The browser applied ${processed.join(', ')}, or did not report them off, and that processing is in what you hear.` : '';
  $('processednote').hidden = !processed.length;
  $('gainnote').hidden = peak <= 1;
  $('after').hidden = false;
  $('play').disabled = n === 0;
  $('play').focus();
}

// A value and its ± to the ±'s second significant digit (MT-005).
function pm(v, u) {
  const d = Math.max(0, Math.min(3, 1 - Math.floor(Math.log10(u))));
  return `${v.toFixed(d)} ± ${u.toFixed(d)}`;
}

// UI-015: the take's held-note measures, each with its expanded ±, or why not.
function showMeasures(t) {
  const [notes, held, s, sU, sN, e, eU, eN, r, rU, rN] = t;
  const lines = [];
  if (notes === 0) {
    lines.push('No note was held long enough to measure how steady it was or its vibrato: that needs a note held on one pitch for at least 2 s, and steadiness two such seconds after each note\'s first and last half second.');
  } else {
    const secs = (held * 0.008).toLocaleString('en', { maximumFractionDigits: 1 });
    lines.push(`You held ${notes === 1 ? 'one note' : notes + ' notes'} for ${secs} s in all; these are measured on those notes.`);
    lines.push(Number.isNaN(s) ? 'Steadiness: not measured, since it needs at least two whole seconds of held note, after each note\'s first and last half second.'
      : `Steadiness: ${pm(s, sU)} cents, how far your held pitch drifted slower than vibrato, over ${sN} s. Smaller is steadier.`);
    lines.push(Number.isNaN(e) ? 'Vibrato width: not measured.'
      : `Vibrato width: ${pm(e, eU)} cents either side of the note, over ${eN} s.`);
    lines.push(Number.isNaN(r) ? 'Vibrato rate: no regular vibrato between 3 and 10 per second was found.'
      : `Vibrato rate: ${pm(r, rU)} cycles per second, over ${rN} s.`);
  }
  const ul = $('measures');
  ul.replaceChildren(...lines.map((x) => Object.assign(document.createElement('li'), { textContent: x })));
  ul.hidden = false;
  window.squillo.measures = t;
}

const takeCanvas = $('takeline');
const takeCtx = takeCanvas.getContext('2d');
const FRAME_S = 384 / 48000;

// UI-017: every cell of the take, across the line's width, by UI-012's rules.
function showTakeLine(cells, notes) {
  if (!take) return;
  take.cells = cells;
  take.notes = [];
  for (let i = 0; i < notes.length; i += 2) take.notes.push([notes[i] * FRAME_S, (notes[i + 1] + 1) * FRAME_S]);
  $('take').hidden = false;
  drawTake();
}

function playheadS() {
  if (!play) return mark;
  const t = play.from + play.ac.currentTime - play.t0;
  if (play.loop) {
    const [a, b] = play.loop;
    return t < b ? t : a + (t - a) % (b - a);
  }
  return Math.min(take.samples.length / take.rate, t);
}

function drawTake() {
  if (!take || !take.cells) return;
  const w = takeCanvas.width, h = takeCanvas.height, pad = 12;
  takeCtx.clearRect(0, 0, w, h);
  const c = take.cells, n = c.length / 3;
  const [lo, hi] = take.scale;
  const dx = w / Math.max(1, n);
  const y = (v) => pad + (h - 2 * pad) * (1 - (v - lo) / (hi - lo));
  const x = (i) => i * dx;
  const view = [];
  for (let i = 0; i < n; i++) view.push([i, c[3 * i], c[3 * i + 1], c[3 * i + 2]]);
  drawFrames(takeCtx, view, x, y, dx, h, lo, hi);
  // UI-018: each held note, first to last frame, as a bar under the line.
  takeCtx.fillStyle = css('--note');
  for (const [a, b] of take.notes) takeCtx.fillRect(a / FRAME_S * dx, h - 5, (b - a) / FRAME_S * dx, 4);
  const t = playheadS();
  $('prevnote').disabled = prevNote(t) === null;
  $('nextnote').disabled = nextNote(t) === null;
  takeCtx.fillStyle = css('--mark');
  takeCtx.fillRect(Math.round(t / FRAME_S * dx) - 1, 0, 2, h);
  window.squillo.takeLine = { cells: n, mark: t, notes: take.notes, loop: play && play.loop };
  if (play) requestAnimationFrame(drawTake);
}

function seek(t, loop = null) {
  if (!take || run) return;
  mark = Math.max(0, Math.min(take.samples.length / take.rate, t));
  playTake(mark, loop);
}

// UI-018: the held note starting after t, the one starting 0.3 s before it,
// and the stretch Loop repeats from t.
function nextNote(t) { const n = take && take.notes.find((x) => x[0] > t + 0.01); return n ? n[0] : null; }
function prevNote(t) { const n = take && take.notes.filter((x) => x[0] < t - 0.3).pop(); return n ? n[0] : null; }
function loopFrom(t) {
  const end = take.samples.length / take.rate;
  return take.notes.find(([a, b]) => a <= t && t < b) ?? [Math.min(t, end - 0.05), Math.min(end, t + 2)];
}

function toggleLoop() {
  if (!take || run) return;
  const t = playheadS();
  if (play && play.loop) seek(t);
  else { const l = loopFrom(t); seek(Math.max(t, l[0]), l); }
}

function stopPlay() {
  if (!play) return;
  mark = playheadS();
  try { play.src.stop(); } catch { /* already ended */ }
  play.ac.close();
  play = null;
  $('play').disabled = !take;
  $('stopplay').disabled = true;
  $('loop').setAttribute('aria-pressed', 'false');
  drawTake();
}

function playTake(from = 0, loop = null) {
  if (!take || run) return;
  if (from >= take.samples.length / take.rate) from = 0;
  stopPlay();
  // UI-013: the context is created only now, at the singer's own action.
  const ac = new AudioContext({ sampleRate: take.rate });
  ac.resume(); // iOS starts a context suspended unless resumed within the tap
  playInfo.contexts++;
  const buf = ac.createBuffer(1, take.samples.length, take.rate);
  buf.copyToChannel(take.samples, 0);
  const src = ac.createBufferSource();
  src.buffer = buf;
  // UI-014: unity unless a sample exceeds full scale, then the largest gain at which none does.
  const gain = take.peak > 1 ? 1 / take.peak : 1;
  playInfo.gain = gain;
  playInfo.samples = buf.length;
  if (gain === 1) src.connect(ac.destination);
  else { const g = ac.createGain(); g.gain.value = gain; src.connect(g).connect(ac.destination); }
  src.onended = () => { if (play && play.src === src) stopPlay(); };
  if (loop) { src.loop = true; src.loopStart = loop[0]; src.loopEnd = loop[1]; }
  play = { ac, src, t0: ac.currentTime, from, loop };
  $('loop').setAttribute('aria-pressed', loop ? 'true' : 'false');
  src.start(0, from);
  requestAnimationFrame(drawTake);
  $('play').disabled = true;
  $('stopplay').disabled = false;
  $('stopplay').focus();
}

$('start').addEventListener('click', start);
$('stop').addEventListener('click', stop);
$('play').addEventListener('click', () => playTake(0));
// A click is a whole tap on iOS, which may start audio; a touch start may not.
takeCanvas.addEventListener('click', (e) => {
  const r = takeCanvas.getBoundingClientRect();
  seek((e.clientX - r.left) / r.width * take.samples.length / take.rate);
});
takeCanvas.addEventListener('keydown', (e) => {
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
  e.preventDefault();
  seek(playheadS() + (e.key === 'ArrowRight' ? 1 : -1));
});
$('stopplay').addEventListener('click', stopPlay);
$('prevnote').addEventListener('click', () => { const t = prevNote(playheadS()); if (t !== null) seek(t); });
$('nextnote').addEventListener('click', () => { const t = nextNote(playheadS()); if (t !== null) seek(t); });
$('loop').addEventListener('click', toggleLoop);
draw();
